head.script:
scwin.validateCnt = 0;
scwin.validateCnt1 = 0;


scwin.onpageload = function () {
	dlt_sample.insertRow();
};


scwin.validateCal = function(){
	console.log("달력: "+scwin.validateCnt +"번쨰 입니다.");
	localStorage.setItem('log',scwin.validateCnt)
	scwin.validateCnt++;
	return "2023-02-06";
};
scwin.validateText = function(){
	console.log("text: "+scwin.validateCnt1 +"번쨰 입니다.");
	scwin.validateCnt1++;
	return "1234566789";
};

	scwin.checkVal = function() {
		return localStorage.getItem('log') == 0;
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_chkGrid_cell_0_0_calendar_img').click()");
		WebSquare.wUnit.addCommand("pause", "400");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('mf_mf_grd_chkGrid_cell_0_0_calendar_calendar_cell_2_2').click()");
		WebSquare.wUnit.addCommand("pause", "400");

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
	localStorage.removeItem("log");
